package com.railway.servlet;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import com.railway.dao.UserDao;import com.railway.util.*;
public class RegisterServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/register.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String n=r.getParameter("fullName"),e=r.getParameter("email"),p=r.getParameter("phone"),pw=r.getParameter("password");if(!Validation.name(n)||!Validation.email(e)||!Validation.phone(p)||pw==null||pw.length()<10||pw.length()>72){r.setAttribute("error","Enter a valid name, email, phone and password (10–72 characters).");doGet(r,s);return;}try{new UserDao().create(n.trim(),e.trim(),p.trim(),Passwords.hash(pw));s.sendRedirect(r.getContextPath()+"/login?registered=1");}catch(java.sql.SQLIntegrityConstraintViolationException ex){r.setAttribute("error","An account with this email already exists.");doGet(r,s);}catch(Exception ex){getServletContext().log("Registration failed",ex);r.setAttribute("error","Registration could not be completed. Please try again.");doGet(r,s);}}}
